func validateBackupSchedule() error {
	if Server.Backup.Schedule == "" {
		return nil
	}
	if duration, err := time.ParseDuration(Server.Backup.Schedule); err == nil {
		if duration <= 0 {
			err = fmt.Errorf("backup.schedule duration must be positive")
			log.Error("Invalid backup.schedule", "schedule", Server.Backup.Schedule, err)
			return err
		}
		Server.Backup.Schedule = "@every " + Server.Backup.Schedule
	} else if strings.HasPrefix(Server.Backup.Schedule, "@every ") {
		if duration, err := time.ParseDuration(strings.TrimPrefix(Server.Backup.Schedule, "@every ")); err == nil && duration <= 0 {
